#!/usr/bin/env node
/**
 * Build-time codegen: turns the TypeScript event registry into the data-only
 * mirror the standalone plugin fallback consumes, plus the plugin's
 * `hooks.json`. Run automatically by `npm run build` (after `tsup`), so the
 * generated files are committed and always present at hook-run time —
 * `dispatch.mjs` never depends on the build having run on the user's machine.
 *
 * Single source of truth: edit `src/core/events.ts` (+ the locales) and rebuild;
 * never hand-edit the generated files below. CI runs this and fails if the
 * committed output drifts (see the stale-check in the workflow).
 *
 * Inputs:  `dist/events.js` (compiled registry) + `src/locales/*.json`
 * Outputs: `plugin/hooks/dispatch.data.mjs`, `plugin/hooks/hooks.json`
 */
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, "..");

const distEvents = resolve(root, "dist", "events.js");
const { EVENTS } = await import(pathToFileURL(distEvents).href);

const ptBR = readJson(resolve(root, "src", "locales", "pt-BR.json"));
const enUS = readJson(resolve(root, "src", "locales", "en-US.json"));
const LOCALES = { "pt-BR": ptBR, "en-US": enUS };

// --- Build the data-only payload ----------------------------------------

const events = {};
for (const e of EVENTS) {
  events[e.name] = {
    configKey: e.configKey,
    defaultEnabled: e.defaultEnabled,
    verbose: e.verbose,
    sound: e.sound,
    resolver: e.resolver ?? null,
    scenario: e.scenario ?? null,
  };
}

// Embedded fallback translations: just title + body fallback per language.
// The embedded path is deliberately "dumb" — the rich resolvers live in the
// TypeScript path, which is what runs unless the CLI module is unreachable.
const translations = {};
for (const lang of Object.keys(LOCALES)) {
  const dict = LOCALES[lang];
  translations[lang] = {};
  for (const e of EVENTS) {
    translations[lang][e.name] = {
      title: dict[e.titleKey] ?? e.name,
      body: dict[e.bodyKey] ?? "",
    };
  }
}

const data = { events, translations };

const dispatchDataPath = resolve(root, "plugin", "hooks", "dispatch.data.mjs");
const banner =
  "// @generated by scripts/gen-dispatch-data.mjs from src/core/events.ts — DO NOT EDIT.\n" +
  "// Run `npm run build` to regenerate after changing the event registry or locales.\n";
writeFileSync(
  dispatchDataPath,
  `${banner}export const DISPATCH_DATA = ${JSON.stringify(data, null, 2)};\n`,
  "utf8",
);

// --- Regenerate hooks.json ------------------------------------------------
// SessionStart (update check) + one block per notification event. The event
// list is derived from the registry so it can never drift from the TS path.

const hookEntry = (event) => ({
  hooks: [
    {
      type: "command",
      command: "node",
      // ${CLAUDE_PLUGIN_ROOT} is a literal placeholder Claude Code expands at
      // hook time — not a JS template expression.
      // biome-ignore lint/suspicious/noTemplateCurlyInString: literal Claude Code placeholder
      args: ["${CLAUDE_PLUGIN_ROOT}/hooks/dispatch.mjs", event],
    },
  ],
});

const hooks = { SessionStart: [hookEntry("SessionStart")] };
for (const e of EVENTS) {
  hooks[e.name] = [hookEntry(e.name)];
}

const hooksPath = resolve(root, "plugin", "hooks", "hooks.json");
writeFileSync(hooksPath, `${JSON.stringify({ hooks }, null, 2)}\n`, "utf8");

// Format the generated files with Biome so their on-disk form matches the
// linter exactly. Without this the committed output (formatted by `biome`)
// would differ from a fresh `JSON.stringify` run, breaking the CI stale-check.
formatWithBiome([dispatchDataPath, hooksPath]);

console.log(
  `[gen-dispatch-data] wrote ${EVENTS.length} events to dispatch.data.mjs and hooks.json`,
);

function readJson(path) {
  return JSON.parse(readFileSync(path, "utf8"));
}

function formatWithBiome(files) {
  try {
    const require = createRequire(import.meta.url);
    const biomeBin = require.resolve("@biomejs/biome/bin/biome");
    const result = spawnSync(process.execPath, [biomeBin, "format", "--write", ...files], {
      cwd: root,
      stdio: "ignore",
    });
    if (result.status !== 0) {
      console.warn("[gen-dispatch-data] biome format returned non-zero; output left unformatted");
    }
  } catch (err) {
    console.warn("[gen-dispatch-data] could not format generated files:", err?.message ?? err);
  }
}
